shots.draw_js:
clearScene();setBig(null);
setEq("$$\\hat Q(s,a;w)\\ \\longrightarrow\\ \\pi(s)=\\arg\\max_a \\hat Q(s,a;w)$$","top");
note("策略是读出来的",640,300,"b lg");
note("而且一定是确定性的",640,360,"r lg");
setCap("前七讲的结构都一样：<b>估值函数，再取 argmax</b>。");

clearScene();setEq(null);
setBig("值方法已经够了","策略是 Q 的副产品，本来就该这么来");
setCap("在表格 MDP 上这是对的。<b>问题在它之外的三类情形。</b>");

clearScene();setBig(null);setEq(null);
note("① 领域知识更好注入",360,260,"b lg","start");
note("② 连续 / 高维动作",360,340,"v lg","start");
note("③ 能表示随机策略",360,420,"g lg","start");
setCap("三个理由。前两个是<b>便利</b>，第三个是<b>必需</b>。");

clearScene();setBig(null);
setEq("$$\\arg\\max_{a\\in\\mathbb{R}^d} \\hat Q(s,a;w)\\ \\ \\text{?}$$","top");
note("动作连续时这不是查表",640,300,"r lg");
note("每一步都要解一次优化",640,360,"r lg");
setCap("动作连续时，<b>argmax 本身变成一个优化问题</b> —— 每决策一次就要解一次。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"注入知识",sub:"便利",state:"on"},
  {label:"连续动作",sub:"便利（但很重要）",state:"on"},
  {label:"随机策略",sub:"必需",state:"on"}]});
note("只有第三条是不可替代的",640,420,"y");
setCap("<b>指名反驳</b>：值方法在表格 MDP 上够用 —— <b>而这一讲要走出表格 MDP</b>。");

clearScene();setBig(null);setEq(null);
note("石",420,290,"b lg");
note("剪",640,290,"b lg");
note("布",860,290,"b lg");
setCap("石头剪刀布。<b>最优策略是什么？</b>三行就能算完。");

clearScene();setEq(null);
setBig("最优策略是确定性的","L2 第五集不是证过吗");
setCap("L2 那条定理<b>完全正确</b> —— 但它有三个前提，这里违反了第一条。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:300,items:[
  {label:"单智能体",sub:"环境不会适应你",state:"on"},
  {label:"完全可观测",sub:"状态是充分统计量",state:"on"},
  {label:"无限时域折扣",sub:"且状态动作有限",state:"on"}]});
note("三条都要，缺一不可",640,420,"y");
setCap("L2 那条定理的三个前提。<b>这一讲的两个例子各违反一条。</b>");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:260,items:[
  {label:"总出石",sub:"最坏收益 −1",state:"dead"},
  {label:"总出剪",sub:"最坏收益 −1",state:"dead"},
  {label:"总出布",sub:"最坏收益 −1",state:"dead"},
  {label:"均匀随机",sub:"收益 0",state:"on"}]});
note("穷举完了，没有第四种确定性策略",640,420,"y");
setCap("<b>任何</b>确定性策略的最坏收益都是 <b>−1</b>；均匀随机是 <b>0</b>。");

clearScene();setBig(null);setEq(null);
note("定理没错",400,290,"g lg");
note("前提不满足",880,290,"r lg");
note("环境会适应你",640,400,"y lg");
setCap("<b>指名反驳</b>：L2 的定理成立，但<b>有对手时环境不再是固定的 MDP</b>。");

clearScene();setBig(null);setEq(null);
gridworld({rows:1,cols:5,cs:110,y:250,x:340,
  tag:function(i,j){return "s"+(j+1);},
  cls:function(i,j){return (j===1||j===3)?"v":"b";},
  val:function(i,j){return (j===1||j===3)?"同":"";}});
note("两格的观测完全一样",640,400,"v");
note("可是最优动作相反",640,448,"r");
setCap("没有对手，只是<b>你看不全</b>：两个不同的格子，观测到的特征一模一样。");

clearScene();setEq(null);
setBig("加特征就能区分","把观测做得更细不就行了");
setCap("能加当然加 —— 但很多时候<b>你能观测到的就这么多</b>。");

clearScene();setBig(null);
setEq("$$x(s_2)=x(s_4)\\ \\Longrightarrow\\ \\pi(x(s_2))=\\pi(x(s_4))$$","top");
note("确定性策略被迫做同样的事",640,310,"r lg");
setCap("确定性策略是<b>观测的函数</b>：观测相同，输出必然相同。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"确定性",sub:"两格做同一件事 · 卡死",state:"dead"},
  {label:"随机",sub:"两边都有概率 · 能走出去",state:"on"},
  {label:"代价",sub:"有时走错，但不卡死",state:"on"}]});
note("随机性在这里是逃生口",640,420,"y");
setCap("随机策略以一定概率两边都试 —— <b>可能走错，但不会永远卡住</b>。");

clearScene();setBig(null);setEq(null);
note("对手（第二集）",400,280,"r lg");
note("看不全（这一集）",880,280,"r lg");
note("两条都要随机策略",640,400,"g lg");
setCap("<b>指名反驳</b>：加特征在信息不存在时无效。<b>随机性是策略的一部分。</b>");
